    #[test]
    fn test_transpose_square() {
        let input = vec![
            vec![1, 2, 3],
            vec![4, 5, 6],
            vec![7, 8, 9],
        ];
        let out = column_stack(input, 3, 3);
        let expected = vec![
            vec![1, 4, 7],
            vec![2, 5, 8],
            vec![3, 6, 9],
        ];
        assert_eq!(out, expected);
    }

    #[test]
    fn test_transpose_rectangular() {
        let input = vec![
            vec![10, 20],
            vec![30, 40],
            vec![50, 60],
        ];
        // input is 3×2, so the transpose is 2×3
        let out = column_stack(input, 2, 3);
        let expected = vec![
            vec![10, 30, 50],
            vec![20, 40, 60],
        ];
        assert_eq!(out, expected);
    }
